const input = $input.first().json;

return [{
  json: {
    subject: input.subject || input.Sujet || 'Marketing digital en Afrique',
    network: input.network || input.Reseau || 'all',
    format: input.format || input.Format || 'texte',
    rubrique: input.rubrique || input.Rubrique || 'Tips',
    hook: input.hook || input.Contenu || '',
    hashtags: input.hashtags || input.Hashtags || '',
    media_prompt: input.media_prompt || input.Media_Prompt || '',
    context: input.context || ''
  }
}];

const response = $input.first().json;
const inputData = $('Normaliser — Input').first().json;

let parsed;
try {
  const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  throw new Error('Erreur parsing posts: ' + e.message);
}

const posts = parsed.posts || {};
const mediaSuggestion = parsed.media_suggestion || {};

return [{
  json: {
    subject: inputData.subject,
    posts,
    media_suggestion: mediaSuggestion,
    generated_at: new Date().toISOString(),
    status: 'à_valider'
  }
}];

